SELECT
,T2.REP_ASSET_TYPE ,T2.REP_TRADE_MARKET ,T3.REP_PRIVATEFUND_FLAG ,T3.REP_PPPFLAG ,T3.REP_SMALLCREDIT ,T3.REP_BONDTOSTOCK_FLAG ,T3.REP_PRIVATEPRD_FLAG ,T3.REP_INSTIT_SIZE ,T3.REP_ASSIGNEE FROM REP_OTHER_INVEST_TARGET T1 INNER JOIN REP_ASSET_DEPT T2 ON T2.REP_FINPROD_ID = T1.REP_FINPROD_ID LEFT JOIN REP_ASSET_OTHER T3 ON T3.REP_FINPROD_ID = T1.REP_FINPROD_ID
AND T1.REP_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
